-- ranking-small.sql
--
-- Standalone fixture for R4 and R10.
--
-- S1  2026-06-01 … 2026-06-30  MONTHLY    9 employees, one country (SWE).
--                                          n=9 → percentiles suppressed, rankings still emitted.
--                                          monthlyRate: 900 800 700 600 500 400 300 200 100 (E01..E09).
--
-- S2  2026-07-01 … 2026-07-31  BI_WEEKLY  1 employee (E01), 1400.00 USD.
--                                          daysCovered=14, daysInMonth=31
--                                          monthlyRate = 1400/14*31 = 3100.00.
--
-- Reference currency: USD. Rate: 1 USD = 1 USD.

